dna = ""
k = 15
Alist = [0.273, 0.379, 0.273, 0.182, 0.258, 0.212, 0.212, 0.318, 0.182, 0.227, 0.333, 0.364, 0.212, 0.258, 0.212]
Clist = [0.212, 0.197, 0.182, 0.227, 0.227, 0.227, 0.288, 0.167, 0.318, 0.182, 0.182, 0.227, 0.258, 0.258, 0.197]
Glist = [0.258, 0.167, 0.242, 0.348, 0.242, 0.273, 0.242, 0.273, 0.288, 0.227, 0.212, 0.212, 0.182, 0.242, 0.318]
Tlist = [0.258, 0.258, 0.303, 0.242, 0.273, 0.288, 0.258, 0.242, 0.212, 0.364, 0.273, 0.197, 0.348, 0.242, 0.273]

def probability(kmer):
    product = 1
    for i in range(k):
        if kmer[i] == "A":
            product *= Alist[i]
        elif kmer[i] == "C":
            product *= Clist[i]
        elif kmer[i] == "G":
            product *= Glist[i]
        elif kmer[i] == "T":
            product *= Tlist[i]
    return product

def generate_kmers():
    kmers=[]
    for i in range(len(dna)-k+1):
        kmer = dna[i:i+k]
        kmers.append(kmer)
    return kmers

def most_probable():
    kmers_dict={}
    for kmer in generate_kmers():
        kmers_dict[kmer] = probability(kmer)
    return max(kmers_dict, key=kmers_dict.get)
print(most_probable())